//from time to bpm is (iTime)
float pi = 3.1415926;
float BPMValue = 60.;

float current_bar()
{
    return ((BPMValue/60.) * iTime * 0.25);
}

float current_beat() {
    return current_bar() * 4.;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    float col = mod(current_bar(), 1.);

    // Output to screen
    fragColor = vec4(col, col, col, 1.0);
}
